<template><div class="integration-workspace"><p v-if="context.error.value" role="alert">{{ context.error.value }} <button class="btn subtle" @click="context.refresh">Retry integration</button></p><p v-if="context.status.value!=='ready'">Source preparation: {{ context.status.value }}. Complete Core analysis runs in a background worker.</p><IntegrationCohortSelector v-if="ready" :context="context" /><div class="integration-grid"><IntegrationFigure v-for="id in ids" :key="speciesId+id" :chart-id="id" :figure="context.charts[id]" :context="context" :species-id="speciesId" :class="{'integration-wide':['OV01','OV02','OV03'].includes(id)}" @selection="selection=$event" @entity="$emit('entity',$event)" /></div><button class="btn subtle" @click="$emit('cross')">Open X1 complete cross-omics evidence</button><IntegrationMembers :context="context" :species-id="speciesId" :selection="selection" @close="selection=null" @entity="$emit('entity',$event)" /></div></template>
<script setup>import {ref,watch,computed} from 'vue';import IntegrationFigure from './IntegrationFigure.vue';import IntegrationMembers from './IntegrationMembers.vue';import IntegrationCohortSelector from './IntegrationCohortSelector.vue';defineEmits(['entity','cross']);const props=defineProps({context:Object,speciesId:String});const selection=ref(null),ids=['OV01','OV02','OV03','OV04','OV05'];const ready=computed(()=>props.context.manifest.value?.status==='ready')
watch(()=>props.context.manifest.value?.artifact_version,()=>selection.value=null)
</script>
<style src="./integration.css"></style>
